import math

class MultilingualSearchEngine:
    def __init__(self, documents: list[str], n: int = 3):
        self.documents = documents
        self.n = n
        self.doc_vectors = [self.char_ngrams(doc) for doc in documents]

    def char_ngrams(self, text: str, n: int = None) -> dict:
        if n is None:
            n = self.n
        text = text.lower()
        counts = {}
        for i in range(len(text) - n + 1):
            gram = text[i:i + n]
            counts[gram] = counts.get(gram, 0) + 1
        return counts

    def cosine_similarity(self, vec_a: dict, vec_b: dict) -> float:
        norm_a = math.sqrt(sum(v * v for v in vec_a.values()))
        norm_b = math.sqrt(sum(v * v for v in vec_b.values()))
        if norm_a == 0 or norm_b == 0:
            return 0.0
        if len(vec_a) > len(vec_b):
            vec_a, vec_b = vec_b, vec_a
        dot = sum(v * vec_b.get(k, 0) for k, v in vec_a.items())
        return dot / (norm_a * norm_b)

    def search(self, query: str, top_k: int = 3) -> list[dict]:
        q = self.char_ngrams(query)
        scored = [
            {"document": doc, "score": self.cosine_similarity(q, vec)}
            for doc, vec in zip(self.documents, self.doc_vectors)
        ]
        scored.sort(key=lambda r: r["score"], reverse=True)
        return scored[:top_k]


# Test it:
engine = MultilingualSearchEngine([
    "machine learning algorithms",
    "deep neural networks",
    "cooking pasta recipes",
    "machine learning models"
])

results = engine.search("machine learning", top_k=2)
print(len(results))
print(results[0]["document"])
print(results[0]["score"] > results[1]["score"])

import math

class LanguageDetector:
    def __init__(self, profiles: dict[str, str], n: int = 3):
        self.n = n
        self.profiles = {}
        for lang, sample in profiles.items():
            self.profiles[lang] = self.char_ngrams(sample)

    def char_ngrams(self, text: str) -> dict:
        text = text.lower()
        ngrams = {}
        for i in range(len(text) - self.n + 1):
            gram = text[i:i + self.n]
            ngrams[gram] = ngrams.get(gram, 0) + 1
        return ngrams

    def cosine_similarity(self, vec_a: dict, vec_b: dict) -> float:
        shared = set(vec_a) & set(vec_b)
        dot = sum(vec_a[w] * vec_b[w] for w in shared)
        mag_a = math.sqrt(sum(v**2 for v in vec_a.values()))
        mag_b = math.sqrt(sum(v**2 for v in vec_b.values()))
        if mag_a == 0 or mag_b == 0:
            return 0.0
        return dot / (mag_a * mag_b)

    def detect(self, text: str) -> str:
        vec = self.char_ngrams(text)
        best_lang = None
        best_score = -1.0
        for lang, profile in self.profiles.items():
            score = self.cosine_similarity(vec, profile)
            if score > best_score:
                best_score = score
                best_lang = lang
        return best_lang

# Test it:
detector = LanguageDetector({
    "english": "the quick brown fox jumps over the lazy dog and the cat",
    "french": "le petit renard brun saute par dessus le chien paresseux",
    "spanish": "el rápido zorro marrón salta sobre el perro perezoso"
})

print(detector.detect("the dog is running fast"))
print(detector.detect("le chat est sur la table"))
print(detector.detect("el gato está en la mesa"))
